export class STOPFramework {
  constructor() {
    this.modules = [];
  }

  registerModule(module) {
    this.modules.push(module);
  }

  selfTest() {
    return this.modules.every(module => module.test());
  }

  optimize() {
    this.modules.forEach(module => module.optimize());
  }

  prioritize() {
    this.modules.sort((a, b) => b.priority - a.priority);
  }

  execute() {
    if (this.selfTest()) {
      this.optimize();
      this.prioritize();
      this.modules.forEach(module => module.execute());
    }
  }
}
